const D = { scale:1, n:6, energy:.6, speed:1, density:.5, hue:320, x:.5, y:.6, spread:.8, lean:.5, style:'retro', pal:'candy', act:'rink', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const PI=Math.PI, TAU=Math.PI*2;
const fr=i=>{const q=Math.sin(i*127.1+P.seed*311.7)*43758.5453; return q-Math.floor(q);};
const hw=h=>((h%360)+360)%360;
const lp=(a,b,t)=>a+(b-a)*t;
const clamp=(v,a,b)=>v<a?a:v>b?b:v;
const u=Math.min(width,height);
const mode=P.style;
const WF = mode==='wireframe';
const SIL = mode==='silhouette';
const CH = mode==='chrome';
const N=Math.max(3, Math.min(12, Math.round(P.n)));
const inten=0.5+0.6*K.intensity;
const eA=0.45+0.85*P.energy;

// ---- palettes ----
const PALSET={ candy:[330,285,50,190], sunset:[15,340,275,45], cool:[195,215,160,255], mono:[hw(P.hue)] };
function skHue(i){
  if(P.pal==='rainbow') return hw(i/N*360 + K.t*6);
  const arr=PALSET[P.pal]||PALSET.candy;
  return hw(arr[i%arr.length] + (fr(i*2+1)-0.5)*16);
}

// ---- shared per-skater draw state (assigned in loop) ----
let sc=1, hue=320, kick=0;
function paint(c,a){
  if(WF){ noFill(); stroke(c[0],c[1],c[2], a==null?100:a); strokeWeight(1.5*sc); }
  else if(SIL){ noStroke(); fill(0,0,9, a==null?100:a); }
  else { noStroke(); fill(c[0], c[1], CH?Math.min(c[2]+8,100):c[2], a==null?100:a); }
}
function limb(x1,y1,x2,y2,w,c){
  if(SIL) stroke(0,0,9); else stroke(c[0],c[1],CH?Math.min(c[2]+8,100):c[2],100);
  strokeWeight(w*(WF?0.85:1)*sc); strokeCap(ROUND); line(x1,y1,x2,y2);
}
function skate(fx,wheel){
  paint(SIL?[0,0,9]:[0,0,96]); rect(fx-6*sc, -2.5*sc, 13*sc, 5*sc, 1.5);
  paint(wheel); ellipse(fx-3*sc,4*sc,4.2*sc,4.2*sc); ellipse(fx+6*sc,4*sc,4.2*sc,4.2*sc);
}

// ---- orbit accumulator (integrates variable rate; tolerates t0 reset) ----
const dirMul = P.act==='couples'?0.55 : P.act==='jam'?1.55 : 1;
const angSpeed=(0.30 + 0.80*K.intensity)*P.speed*dirMul;
if(S.acc==null) S.acc=0;
if(S.lastT==null || K.t<S.lastT) S.lastT=K.t;
S.acc += (K.t - S.lastT)*angSpeed; S.lastT=K.t;
const globalAng=S.acc;

// ---- rink geometry ----
const cx=width*P.x, cy=height*P.y;
const rx=u*(0.26+0.20*P.spread);
const ry=rx*0.34;
const sBase=u*0.0052*P.scale;

// ---- rink floor: dark gloss + rotating spotlights (real-time, lifts luminance) ----
push();
noStroke();
fill(hw(P.hue+180), 32, 15, 62);
ellipse(cx, cy, rx*2.6, ry*3.0);
fill(0,0,4,40);
ellipse(cx, cy, rx*2.6, ry*3.0);
blendMode(ADD);
const sweepN=Math.max(3, Math.round(3+P.density*4));
for(let s=0;s<sweepN;s++){
  const sa=K.t*0.55 + s/sweepN*TAU;
  const lx=cx+Math.cos(sa)*rx*0.85, ly=cy+Math.sin(sa)*ry*0.85;
  fill(hw(P.hue + s*47 + K.t*12), 72, 92, (5+9*K.pulse+9*A.bass)*(0.45+P.density*0.9));
  ellipse(lx, ly, rx*0.55, ry*1.1);
}
blendMode(BLEND);
pop();

// ---- build skaters, sort back-to-front ----
const list=[];
for(let i=0;i<N;i++){
  let off;
  if(P.act==='couples'){ const pr=Math.floor(i/2), np=Math.ceil(N/2); off = pr/np*TAU + (i%2)*0.30 + fr(pr)*0.35; }
  else off = i/N*TAU + (fr(i)-0.5)*0.5;
  const a=off + globalAng;
  const px=cx + rx*Math.cos(a);
  const py=cy + ry*Math.sin(a);
  const depth=(Math.sin(a)+1)/2;
  list.push({i,a,px,py,depth});
}
list.sort((p,q)=>p.depth-q.depth);

// ---- draw skaters ----
const spinEvery = P.act==='jam'?6 : P.act==='couples'?26 : 13;
for(const sk of list){
  const i=sk.i, a=sk.a, depth=sk.depth;
  sc = sBase * lp(0.60,1.18,depth);
  hue = skHue(i);
  kick = clamp(K.pulse*inten + A.bass*0.7, 0, 1);
  const facing = Math.sin(a)>0 ? -1 : 1;

  // stride tied to orbit speed
  const stride = globalAng*4 + i*1.3;
  const legL = Math.sin(stride)*eA;
  const legR = Math.sin(stride+PI)*eA;
  // crossover peaks at the tight turns (major-axis ends)
  const cross = Math.pow(Math.abs(Math.cos(a)),2) * (0.5+0.6*P.energy);
  // occasional spin
  const sp = (((K.beat + fr(i*9)*spinEvery) % spinEvery)+spinEvery)%spinEvery;
  const spinAmt = sp<1.25 ? sp/1.25 : 0;
  const bodyScaleX = spinAmt>0 ? Math.cos(spinAmt*TAU) : 1;
  const tilt = facing * P.lean * 0.34 * (0.4+0.6*eA) + (bodyScaleX<0?0:0);

  const body=[hue,72,92];
  const short=[hw(hue+(P.pal==='mono'?0:170)),58,68];
  const sock=[hw(hue+62),82,95];
  const skin=[28,40,82];
  const hairH=fr(i*3)>0.5?20:340; const hair=[hairH,45,fr(i*3)>0.5?24:14];
  const wheel=[hw(hue+120),90,100];

  push();
  translate(sk.px, sk.py);
  if(!WF && !SIL){ noStroke(); fill(0,0,0,26); ellipse(0, 4*sc, 26*sc*(0.7+0.5*depth), 6.5*sc); }

  // spotlight pool
  push(); blendMode(ADD); noStroke();
  for(let r=3;r>0;r--){ fill(hue,55,90,(4+kick*7)*(0.45+P.density*0.6)); ellipse(0,-8*sc,(28+r*12)*sc,(44+r*10)*sc); }
  blendMode(BLEND); pop();

  rotate(tilt);
  scale(facing*bodyScaleX, 1);
  if(WF||CH){ drawingContext.shadowBlur=7*sc; drawingContext.shadowColor='hsl('+Math.round(hue)+',90%,62%)'; }

  // ---- legs (crossover stride) ----
  const footLx=(-7 + legL*8 + cross*15)*sc;
  const footRx=( 7 + legR*8 - cross*15)*sc;
  const kneeLx=lp(-5*sc, footLx, 0.5) - 1.5*sc;
  const kneeRx=lp( 5*sc, footRx, 0.5) + 1.5*sc;
  // draw the trailing (further) leg first — pick by stride so front leg overlays
  const leftFront = legL >= legR;
  function drawLeg(hipx, kneex, footx, swing){
    limb(hipx, -28*sc, kneex, -15*sc, 6.5, short);
    limb(kneex, -15*sc, footx, -1*sc, 5, sock);
    // tube-sock stripe
    if(!WF && !SIL){ paint([hw(hue+62),20,100]); rect(footx-2.5*sc, -9*sc, 5*sc, 2*sc); }
    skate(footx, wheel);
  }
  if(leftFront){ drawLeg(5*sc,kneeRx,footRx,legR); drawLeg(-5*sc,kneeLx,footLx,legL); }
  else { drawLeg(-5*sc,kneeLx,footLx,legL); drawLeg(5*sc,kneeRx,footRx,legR); }

  // ---- shorts ----
  paint(short);
  beginShape(); vertex(-9*sc,-30*sc); vertex(9*sc,-30*sc); vertex(8*sc,-22*sc); vertex(-8*sc,-22*sc); endShape(CLOSE);

  // ---- torso / tank top ----
  paint(body);
  beginShape(); vertex(-8*sc,-30*sc); vertex(8*sc,-30*sc); vertex(9*sc,-47*sc); vertex(-9*sc,-47*sc); endShape(CLOSE);
  if(!WF && !SIL){
    // core shade + rim
    noStroke();
    fill(body[0],body[1]+6,body[2]-26,34); beginShape(); vertex(-9*sc,-30*sc); vertex(-4*sc,-30*sc); vertex(-5*sc,-46*sc); vertex(-9*sc,-47*sc); endShape(CLOSE);
    fill(0,0,100,20+kick*18); beginShape(); vertex(6*sc,-31*sc); vertex(9*sc,-47*sc); vertex(6*sc,-47*sc); vertex(4*sc,-31*sc); endShape(CLOSE);
  }
  if(CH){ push(); blendMode(ADD); noStroke(); fill(hue,22,100,42+kick*30); ellipse(0,-38*sc,14*sc,20*sc); blendMode(BLEND); pop(); }
  // shimmer on beat
  if(!WF && !SIL){ push(); blendMode(ADD); noStroke(); fill(hue,30,100,kick*30); ellipse(0,-38*sc,16*sc,22*sc); blendMode(BLEND); pop(); }

  // ---- arms (swing opposite legs; raise on spin) ----
  const raise=spinAmt;
  const shy=-45*sc;
  const hLx=(-9 - legR*9)*sc, hLy=shy + lp(6*sc,-16*sc,raise) + legR*4*sc;
  const hRx=( 9 - legL*9)*sc, hRy=shy + lp(6*sc,-16*sc,raise) - legL*4*sc;
  limb(-7*sc, shy, hLx, hLy, 4.5, body); paint(skin); ellipse(hLx,hLy,5.5*sc,5.5*sc);
  limb( 7*sc, shy, hRx, hRy, 4.5, body); paint(skin); ellipse(hRx,hRy,5.5*sc,5.5*sc);

  // ---- head ----
  const headBob=Math.sin(stride*0.5)*1.4*sc;
  push(); translate(0,headBob);
  // ponytail sway
  const pt=Math.sin(K.t*3+i)*3*sc;
  paint(hair); if(!WF){ ellipse(-8*sc+pt*0.3, -52*sc, 7*sc, 13*sc); }
  paint(skin); ellipse(0,-54*sc,13*sc,14*sc);
  // hair cap
  paint(hair); arc(0,-56*sc,15*sc,15*sc, PI+0.2, TAU-0.2, WF?undefined:CHORD);
  // headband
  paint([hw(hue+40),85,95]); rect(-7.5*sc,-57*sc,15*sc,2.6*sc,1);
  if(!WF && !SIL){ noStroke(); fill(0,0,12); ellipse(3*sc,-54*sc,1.8*sc,1.8*sc); } // eye (facing right)
  pop();

  if(WF||CH) drawingContext.shadowBlur=0;
  pop();
}
blendMode(BLEND);
strokeCap(ROUND);
